/* 页面守卫：同步、尽早执行。未登录跳登录页，未审核 / 权限不足跳用户中心。
 * 权限分级（v2）：
 *   status  pending / active / rejected / disabled —— 只有 active 能浏览站内内容
 *   level   0 无权限 / 1 普通成员 / 2 核心朋友 / 9 站主
 *   核心区域（tools/、library、files、upload、resources）要求 level >= 2。
 *   早期线下账号的旧会话没有这两个字段，按「已激活 + 核心朋友」处理，避免把站主锁在门外。
 * 页面可在引入本脚本前设置 window.XINMO_REQUIRED_LEVEL 覆盖所需等级。
 * 注意：这是前端拦截，只挡随手访问；静态文件本身仍可从公开 URL 获取。 */
(function () {
  'use strict';
  // 防点击劫持：GitHub Pages 无法设置 X-Frame-Options，这里用 JS 兜底；被 iframe 嵌入时跳到顶层。
  try {
    if (window.top !== window.self) { window.top.location = window.self.location.href; return; }
  } catch (e) { document.documentElement.style.display = 'none'; }
  var cfg = window.XINMO_ACCESS;
  if (!cfg || !cfg.accounts || !cfg.accounts.length || !cfg.gate) return;

  var src = (document.currentScript && document.currentScript.src) || '';
  var marker = 'assets/js/guard.js';
  var at = src.indexOf(marker);
  var root = at >= 0 ? src.slice(0, at) : '/';
  var KEY = 'xinmo_access';

  function read() {
    try { return JSON.parse(localStorage.getItem(KEY) || 'null'); }
    catch (e) { return null; }
  }

  var s = read();
  var ok = s && s.t === cfg.gate && s.exp && s.exp > Date.now();
  if (!ok) {
    try { localStorage.removeItem(KEY); } catch (e) {}
    location.replace(root + 'login.html?next=' + encodeURIComponent(location.href));
    return;
  }

  var status = s.status || 'active';
  var level = (typeof s.level === 'number') ? s.level : 2;
  var path = location.pathname.replace(/\\/g, '/');
  var isMe = /(^|\/)me\.html$/i.test(path);
  var CORE_PATHS = [
    /^\/tools\//i, /^\/library\.html$/i, /^\/files\.html$/i,
    /^\/upload\.html$/i, /^\/resources\//i
  ];
  var isCore = CORE_PATHS.some(function (re) { return re.test(path); });
  var need = (typeof window.XINMO_REQUIRED_LEVEL === 'number')
    ? window.XINMO_REQUIRED_LEVEL : (isCore ? 2 : 1);

  // 待审核 / 已拒绝 / 已停用 / 无权限：只能停留在用户中心
  if (!isMe && (status !== 'active' || level < 1)) {
    location.replace(root + 'me.html?pending=1');
    return;
  }
  // 核心区域只对站主认可的朋友开放
  if (!isMe && level < need) {
    location.replace(root + 'me.html?need=core');
    return;
  }

  document.addEventListener('DOMContentLoaded', function () {
    var compact = !!(window.matchMedia && window.matchMedia('(max-width: 640px)').matches);

    /* 站长专属入口：只有在这台浏览器验证过管理口令才会插入 DOM。
       其他访客的浏览器没有这个标记，页面上根本不存在这个链接。
       标记本身不授予任何权限，打开后仍需管理口令。 */
    try {
      if (localStorage.getItem('xinmo_owner_hint') === '1' && !document.getElementById('xinmoOwnerLink')) {
        var owner = document.createElement('a');
        owner.id = 'xinmoOwnerLink';
        owner.href = root + 'owner.html';
        owner.textContent = '站长';
        owner.title = '站长工作台（仅本机可见）';
        var tools = document.querySelector('.header-tools');
        if (tools) {
          owner.className = 'header-link';
          tools.appendChild(owner);
        } else {
          owner.style.cssText = 'position:fixed;z-index:99997;right:14px;bottom:52px;text-decoration:none;' +
            'font:11px/1.2 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif;' +
            'color:inherit;opacity:.34;padding:5px 9px;border-radius:8px;background:rgba(127,127,127,.10);';
          document.body.appendChild(owner);
        }
      }
    } catch (e) {}

    var a = document.createElement('a');
    a.href = '#';
    a.className = 'xinmo-logout';
    a.textContent = '退出';
    a.setAttribute('aria-label', '退出登录');
    a.setAttribute('title', '退出登录');
    var nav = compact ? document.querySelector('.main-nav') : null;
    /* 手机端：有下拉菜单的页面（首页 / 领域模块 / 图片来源）把「退出」收进菜单，
       正文上不再有任何悬浮按钮；其余页面用 42px 实心圆钮，避开底部安全区。 */
    if (nav) {
      a.style.cssText = 'display:block;padding:12px;font-size:15px;color:rgba(255,255,255,.88);' +
        'border-top:1px solid rgba(255,255,255,.16);margin-top:4px;border-radius:6px;';
      nav.appendChild(a);
    } else {
      var base = 'position:fixed;z-index:99998;text-decoration:none;' +
        'font:11px/1.2 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif;';
      a.style.cssText = base + (compact
        ? 'right:12px;bottom:calc(12px + env(safe-area-inset-bottom, 0px));' +
          'width:42px;height:42px;display:grid;place-items:center;border-radius:50%;' +
          'color:#fff;opacity:.92;background:rgba(140,15,20,.92);' +
          'border:1px solid rgba(255,255,255,.42);box-shadow:0 4px 14px rgba(60,3,6,.32);'
        : 'right:14px;bottom:14px;color:inherit;opacity:.38;padding:5px 9px;border-radius:8px;' +
          'background:rgba(127,127,127,.10);');
      if (!compact) {
        a.addEventListener('mouseenter', function () { a.style.opacity = '.8'; });
        a.addEventListener('mouseleave', function () { a.style.opacity = '.38'; });
      }
      document.body.appendChild(a);
    }
    a.addEventListener('click', function (e) {
      e.preventDefault();
      try { localStorage.removeItem(KEY); } catch (err) {}
      location.href = root + 'login.html';
    });
  });
})();
